"use server";

import { paystackRequest } from "./client";

export interface InitializeTransactionParams {
  email: string;
  /** Amount in kobo (smallest currency unit). Multiply NGN by 100. */
  amount: number;
  currency?: string;
  reference?: string;
  metadata?: Record<string, unknown>;
}

export interface InitializeTransactionResult {
  status: boolean;
  message: string;
  data: {
    authorization_url: string;
    access_code: string;
    reference: string;
  };
}

export interface VerifyTransactionResult {
  status: boolean;
  message: string;
  data: {
    id: number;
    status: "success" | "failed" | "abandoned";
    reference: string;
    amount: number;
    currency: string;
    customer: { email: string };
    paid_at: string;
  };
}

export async function initializeTransaction(
  params: InitializeTransactionParams,
): Promise<InitializeTransactionResult> {
  return paystackRequest<InitializeTransactionResult>("POST", "/transaction/initialize", {
    email: params.email,
    amount: params.amount,
    currency: params.currency ?? "NGN",
    reference: params.reference,
    metadata: params.metadata,
  });
}

export async function verifyTransaction(
  reference: string,
): Promise<VerifyTransactionResult> {
  return paystackRequest<VerifyTransactionResult>(
    "GET",
    `/transaction/verify/${reference}`,
  );
}

