import crypto from "crypto";
import { adapter } from "./adapter";

export interface PaystackWebhookEvent {
  event: string;
  data: {
    reference: string;
    amount: number;
    currency: string;
    status: string;
    customer: { email: string; id: number };
    paid_at: string;
    metadata?: Record<string, unknown>;
  };
}

export interface PaymentData {
  reference: string;
  amount: number;
  currency: string;
  status: string;
  email: string;
  paidAt: string;
}

// Constant-time comparison — prevents timing attacks against the HMAC compare.
export function verifyWebhookSignature(
  body: string,
  signature: string,
  secretKey: string,
): boolean {
  const hash = crypto
    .createHmac("sha512", secretKey)
    .update(body)
    .digest("hex");
  const a = Buffer.from(hash, "utf8");
  const b = Buffer.from(signature, "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

export async function handlePaystackEvent(event: PaystackWebhookEvent) {
  switch (event.event) {
    case "charge.success":
    case "charge.failed": {
      // Paystack delivers the same event multiple times — your adapter should
      // upsert on `reference` (unique constraint) to stay idempotent.
      await adapter.recordPayment({
        reference: event.data.reference,
        amount: event.data.amount,
        currency: event.data.currency,
        status: event.data.status,
        email: event.data.customer.email,
        paidAt: event.data.paid_at,
      });
      break;
    }
    default:
      console.log(`Unhandled Paystack event: ${event.event}`);
  }
}

