"use client";

import { useState, useCallback } from "react";
import { initializeTransaction } from "./actions";

interface CheckoutButtonProps {
  email: string;
  /** Amount in kobo (smallest currency unit). Multiply NGN by 100. */
  amount: number;
  currency?: string;
  metadata?: Record<string, unknown>;
  label?: string;
  onSuccess?: (transaction: { reference: string }) => void;
  onClose?: () => void;
}

export function PaystackCheckoutButton({
  email,
  amount,
  currency = "NGN",
  metadata,
  label = "Pay Now",
  onSuccess,
  onClose,
}: CheckoutButtonProps) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handlePayment = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const result = await initializeTransaction({ email, amount, currency, metadata });
      const { default: PaystackPop } = await import("@paystack/inline-js");
      const popup = new PaystackPop();

      popup.resumeTransaction(result.data.access_code, {
        onSuccess: (transaction: { reference: string }) => {
          onSuccess?.(transaction);
        },
        onLoad: (response: { accessCode: string }) => {
          console.log("[paystack] popup loaded", response.accessCode);
        },
        onCancel: () => {
          onClose?.();
        },
        onError: (error: { message: string }) => {
          setError(error.message);
          console.error("[paystack] payment error:", error.message);
        },
      });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Payment initialization failed";
      setError(message);
    } finally {
      setLoading(false);
    }
  }, [email, amount, currency, metadata, onSuccess, onClose]);

  return (
    <div>
      <button type="button" onClick={handlePayment} disabled={loading}>
        {loading ? "Processing..." : label}
      </button>
      {error && <p style={{ color: "red", marginTop: "8px" }}>{error}</p>}
    </div>
  );
}

