import { headers } from "next/headers";
import { handlePaystackEvent, verifyWebhookSignature } from "@/infra/paystack/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const signature = headersList.get("x-paystack-signature");

  if (!signature) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.PAYSTACK_SECRET_KEY) {
    console.error("[paystack webhook] PAYSTACK_SECRET_KEY is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (!verifyWebhookSignature(body, signature, process.env.PAYSTACK_SECRET_KEY)) {
    console.error("[paystack webhook] Invalid signature");
    return new Response("Unauthorized", { status: 401 });
  }

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  let event;
  try {
    event = JSON.parse(body);
  } catch (err: unknown) {
    console.error("[paystack webhook] malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so Paystack retries — distinct from 4xx above.
  try {
    await handlePaystackEvent(event);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[paystack webhook] handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}

