import { db } from "@/lib/db";
import type { PaymentData } from "./webhooks";

// Idempotent upsert keyed on `reference` — webhook retries won't duplicate rows.
export const adapter = {
  recordPayment: async (data: PaymentData) => {
    await db.payment.upsert({
      where: { reference: data.reference },
      update: {
        amount: data.amount,
        currency: data.currency,
        status: data.status,
        email: data.email,
        paidAt: new Date(data.paidAt),
      },
      create: {
        reference: data.reference,
        amount: data.amount,
        currency: data.currency,
        status: data.status,
        email: data.email,
        paidAt: new Date(data.paidAt),
      },
    });
  },
};

