import { db } from "@/lib/db";
import { payments } from "@/lib/schema";
import type { PaymentData } from "./webhooks";

// Idempotent insert keyed on `reference` — webhook retries won't duplicate rows.
export const adapter = {
  recordPayment: async (data: PaymentData) => {
    await db
      .insert(payments)
      .values({
        reference: data.reference,
        amount: data.amount,
        currency: data.currency,
        status: data.status,
        email: data.email,
        paidAt: new Date(data.paidAt),
      })
      .onConflictDoUpdate({
        target: payments.reference,
        set: {
          amount: data.amount,
          currency: data.currency,
          status: data.status,
          email: data.email,
          paidAt: new Date(data.paidAt),
        },
      });
  },
};

